#!/usr/bin/env node
/**
 * Materialize a gitignored `pnpm-workspace.yaml` from Nub's SoT
 * (`package.json` → `workspaces.packages` + `workspaces.catalog`) so
 * Changesets / `@manypkg` can discover the monorepo and so
 * `changeset publish` can run a real `pnpm publish` that rewrites
 * `workspace:` / `catalog:` protocols. Those tools only recognize
 * pnpm-workspace.yaml / yarn|npm lockfiles — not Nub identity.
 *
 * The generated file is gitignored. Do not commit it. Do not run
 * `pnpm install` because of it — `nub install` owns the tree.
 *
 * Usage:
 *   node scripts/ensure-manypkg-workspace.js
 *   node scripts/ensure-manypkg-workspace.js --check   # exit 1 if stale/missing
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const HEADER = `# GENERATED by scripts/ensure-manypkg-workspace.js — do not edit or commit.
# Source of truth: package.json → workspaces.packages (+ workspaces.catalog) (Nub).
# Exists so Changesets / @manypkg can discover packages and so pnpm publish
# can rewrite workspace:/catalog: protocols. Install stays on Nub.
`;

/**
 * @param {unknown} pkgJson
 * @returns {string[]}
 */
export function readWorkspacePackages(pkgJson) {
	const packages = pkgJson?.workspaces?.packages;
	if (!Array.isArray(packages) || packages.length === 0) {
		throw new Error(
			'package.json "workspaces.packages" must be a non-empty array (Nub SoT)',
		);
	}
	for (const glob of packages) {
		if (typeof glob !== "string" || glob.trim() === "") {
			throw new Error(
				'package.json "workspaces.packages" entries must be non-empty strings',
			);
		}
	}
	return packages;
}

/**
 * @param {unknown} pkgJson
 * @returns {Record<string, string>}
 */
export function readWorkspaceCatalog(pkgJson) {
	const catalog = pkgJson?.workspaces?.catalog;
	if (catalog == null) return {};
	if (typeof catalog !== "object" || Array.isArray(catalog)) {
		throw new Error(
			'package.json "workspaces.catalog" must be an object of name → version (Nub SoT)',
		);
	}
	/** @type {Record<string, string>} */
	const out = {};
	for (const [name, version] of Object.entries(catalog)) {
		if (typeof name !== "string" || name.trim() === "") {
			throw new Error(
				'package.json "workspaces.catalog" keys must be non-empty strings',
			);
		}
		if (typeof version !== "string" || version.trim() === "") {
			throw new Error(
				`package.json "workspaces.catalog[${JSON.stringify(name)}]" must be a non-empty string`,
			);
		}
		out[name] = version;
	}
	return out;
}

/**
 * @param {string[]} packages
 * @param {Record<string, string>} [catalog]
 * @returns {string}
 */
export function renderPnpmWorkspaceYaml(packages, catalog = {}) {
	let yaml = `${HEADER}packages:\n${packages.map((p) => `  - ${JSON.stringify(p)}`).join("\n")}\n`;
	const catalogNames = Object.keys(catalog).sort();
	if (catalogNames.length > 0) {
		yaml += `catalog:\n${catalogNames.map((name) => `  ${JSON.stringify(name)}: ${JSON.stringify(catalog[name])}`).join("\n")}\n`;
	}
	return yaml;
}

/**
 * @param {{ rootDir?: string, write?: boolean }} [options]
 * @returns {{ path: string, changed: boolean, content: string, packages: string[], catalog: Record<string, string> }}
 */
export function ensureManypkgWorkspace(options = {}) {
	const rootDir = options.rootDir ?? process.cwd();
	const write = options.write !== false;
	const pkgPath = join(rootDir, "package.json");
	const pkgJson = JSON.parse(readFileSync(pkgPath, "utf8"));
	const packages = readWorkspacePackages(pkgJson);
	const catalog = readWorkspaceCatalog(pkgJson);
	const content = renderPnpmWorkspaceYaml(packages, catalog);
	const target = join(rootDir, "pnpm-workspace.yaml");
	const existing = existsSync(target) ? readFileSync(target, "utf8") : null;
	const changed = existing !== content;
	if (write && changed) {
		writeFileSync(target, content);
	}
	return { path: target, changed, content, packages, catalog };
}

const isMain =
	Boolean(process.argv[1]) &&
	import.meta.url === pathToFileURL(resolve(process.argv[1])).href;

if (isMain) {
	const checkOnly = process.argv.includes("--check");
	try {
		const result = ensureManypkgWorkspace({ write: !checkOnly });
		if (checkOnly) {
			if (result.changed) {
				console.error(
					"pnpm-workspace.yaml is missing or stale vs package.json workspaces.packages/catalog.\n" +
						"Run: node scripts/ensure-manypkg-workspace.js",
				);
				process.exit(1);
			}
			console.log(
				"pnpm-workspace.yaml matches Nub workspaces.packages (+ catalog)",
			);
			process.exit(0);
		}
		if (result.changed) {
			const catalogCount = Object.keys(result.catalog).length;
			const catalogNote =
				catalogCount > 0 ? `, ${catalogCount} catalog entries` : "";
			console.log(
				`Wrote ${result.path} (${result.packages.length} globs${catalogNote})`,
			);
		}
	} catch (err) {
		console.error(err instanceof Error ? err.message : err);
		process.exit(1);
	}
}
